<script setup lang="ts">
type SignedUpload={cloudName:string;apiKey:string;timestamp:number;folder:string;publicId:string;signature:string}
type CloudinaryResult={secure_url?:string;error?:{message?:string}}
const props=withDefaults(defineProps<{modelValue:string|number|boolean;multiple?:boolean}>(),{multiple:false})
const emit=defineEmits<{(event:'update:modelValue',value:string):void}>()
const uploading=ref(false),message=ref('')
const imageUrls=computed(()=>String(props.modelValue||'').split(',').map((url)=>url.trim()).filter(Boolean))
function setUrls(urls:string[]){emit('update:modelValue',props.multiple?urls.join(', '):urls[0]||'')}
async function upload(event:Event){const input=event.target as HTMLInputElement;const files=Array.from(input.files||[]);input.value='';if(!files.length)return;message.value='';const allowed=['image/jpeg','image/png','image/webp'];for(const file of files){if(!allowed.includes(file.type)){message.value='Choisissez une image JPG, PNG ou WebP.';return}if(file.size>10*1024*1024){message.value='Chaque image doit faire moins de 10 Mo.';return}if(!props.multiple&&files.length>1){message.value='Un seul fichier peut être téléversé pour ce champ.';return}}uploading.value=true;let uploaded=0;try{for(const file of files){const signed=await $fetch<SignedUpload>('/api/admin/media/sign',{method:'POST'});const form=new FormData();form.append('file',file);form.append('api_key',signed.apiKey);form.append('timestamp',String(signed.timestamp));form.append('folder',signed.folder);form.append('public_id',signed.publicId);form.append('signature',signed.signature);const response=await fetch(`https://api.cloudinary.com/v1_1/${encodeURIComponent(signed.cloudName)}/image/upload`,{method:'POST',body:form});const result=await response.json() as CloudinaryResult;if(!response.ok||!result.secure_url)throw new Error(result.error?.message||`Cloudinary a refusé l’image (HTTP ${response.status}).`);const uploadedUrl=new URL(result.secure_url);if(uploadedUrl.protocol!=='https:'||uploadedUrl.hostname!=='res.cloudinary.com')throw new Error('Cloudinary a retourné une URL non reconnue.');const next=props.multiple?[...imageUrls.value,uploadedUrl.toString()]:[uploadedUrl.toString()];setUrls([...new Set(next)]);uploaded++}message.value=`${uploaded} image${uploaded>1?'s':''} téléversée${uploaded>1?'s':''}.` }catch(error){message.value=(error as{data?:{statusMessage?:string}})?.data?.statusMessage||(error as Error).message||'L’envoi est interrompu ; les fichiers déjà téléversés restent liés au formulaire.'}finally{uploading.value=false}}
function remove(url:string){setUrls(imageUrls.value.filter((item)=>item!==url))}
</script>
<template><div class="cloudinary-uploader"><div class="upload-actions"><label class="upload-button"><input type="file" :multiple="multiple" accept="image/jpeg,image/png,image/webp" :disabled="uploading" @change="upload"><span>{{uploading?'Téléversement…':multiple?'Ajouter des photos':'Choisir une image'}}</span></label><span class="upload-meta">JPG, PNG ou WebP · 10 Mo maximum</span></div><label class="url-field"><span>URL(s) d’image, séparées par des virgules</span><input class="form-control" :value="String(modelValue||'')" type="text" autocomplete="off" placeholder="Les URLs Cloudinary apparaîtront ici" @input="emit('update:modelValue',($event.target as HTMLInputElement).value)"></label><p v-if="message" class="upload-status" role="status">{{message}}</p><ul v-if="imageUrls.length" class="thumbnail-list"><li v-for="url in imageUrls" :key="url"><img :src="url" alt="Aperçu de l’image chargée" loading="lazy"><button type="button" :aria-label="`Retirer ${url}`" @click="remove(url)">Retirer</button></li></ul></div></template>
<style scoped>.cloudinary-uploader{display:grid;gap:.45rem}.upload-actions{display:flex;align-items:center;gap:.6rem;flex-wrap:wrap}.upload-button{display:inline-flex;cursor:pointer;border:1px solid #d7c7bd;border-radius:999px;padding:.48rem .8rem;background:#fffaf6;color:#69433f;font-size:.64rem;font-weight:700}.upload-button input{position:absolute;width:1px;height:1px;opacity:0;pointer-events:none}.upload-button:focus-within{outline:2px solid #783d52;outline-offset:3px}.upload-meta,.url-field>span{color:#8b7e76;font-size:.58rem}.url-field{display:grid;gap:.28rem}.upload-status{margin:0;color:#684334;font-size:.62rem}.thumbnail-list{display:flex;flex-wrap:wrap;gap:.45rem;margin:0;padding:0;list-style:none}.thumbnail-list li{display:flex;align-items:center;gap:.35rem;border:1px solid #e4dbd3;border-radius:.45rem;padding:.25rem;background:white}.thumbnail-list img{width:2.8rem;height:2.8rem;object-fit:cover;border-radius:.32rem}.thumbnail-list button{border:0;background:transparent;color:#773e50;font-size:.58rem;cursor:pointer}</style>
